// SAFE: Null pointer deletion
int* p = nullptr;
delete p;           // No effect, guaranteed safe
delete[] p;         // No effect, guaranteed safe

// UNDEFINED BEHAVIOR: Mismatched new/delete
int* arr = new int[10];
delete arr;         // UB: should be delete[]

int* obj = new int;
delete[] obj;       // UB: should be delete

// UNDEFINED BEHAVIOR: Double-delete
int* p = new int;
delete p;
delete p;           // UB: p is now invalid

// UNDEFINED BEHAVIOR: Use-after-free
int* p = new int(42);
delete p;
int x = *p;         // UB: indirection through invalid pointer

// UNDEFINED BEHAVIOR: Deleting non-heap memory
int stack_var;
delete &stack_var;  // UB: not allocated by operator new

static int global_var;
delete &global_var; // UB: not from dynamic storage

// IMPLEMENTATION-DEFINED: Other uses of invalid pointers
int* p = new int;
delete p;
if (p == nullptr) {} // Implementation-defined (typically p != nullptr)
p = p;              // Implementation-defined

code_example:
#include <iostream>
#include <new>

class Widget {
public:
    Widget(int id) : id_(id) {
        std::cout << "Widget " << id_ << " constructed\n";
    }
    ~Widget() {
        std::cout << "Widget " << id_ << " destroyed\n";
    }
    int id_;
};

void demonstrate_safe_null_delete() {
    std::cout << "=== Safe: Deleting null pointer ===\n";
    Widget* p = nullptr;
    delete p;         // SAFE: no effect
    delete[] p;       // SAFE: no effect
    std::cout << "No crash - null delete is safe\n\n";
}

void demonstrate_mismatched_delete() {
    std::cout << "=== UNDEFINED: Mismatched new[]/delete ===\n";
    Widget* arr = new Widget[3]{1, 2, 3};

    // DANGER: This is UNDEFINED BEHAVIOR
    // delete arr;  // WRONG: should be delete[]

    // Correct:
    delete[] arr;
    std::cout << "Used correct delete[] for array\n\n";
}

void demonstrate_double_delete() {
    std::cout << "=== UNDEFINED: Double delete ===\n";
    Widget* p = new Widget(100);
    delete p;  // First delete: OK

    // DANGER: This is UNDEFINED BEHAVIOR
    // delete p;  // CRASH or corruption: double-delete

    std::cout << "Avoided double-delete by commenting it out\n\n";
}

void demonstrate_use_after_free() {
    std::cout << "=== UNDEFINED: Use-after-free ===\n";
    Widget* p = new Widget(200);
    delete p;

    // DANGER: All of these are UNDEFINED BEHAVIOR
    // std::cout << p->id_;     // Dereferencing invalid pointer
    // Widget* p2 = p;          // Copying invalid pointer (impl-defined)
    // if (p == nullptr) {}     // Comparing invalid pointer (impl-defined)

    // Safe pattern: null the pointer after delete
    p = nullptr;
    if (p == nullptr) {
        std::cout << "Nulled pointer after delete - safe check\n\n";
    }
}

void demonstrate_stack_delete() {
    std::cout << "=== UNDEFINED: Deleting stack variable ===\n";
    Widget stack_widget(300);

    // DANGER: This is UNDEFINED BEHAVIOR
    // delete &stack_widget;  // CRASH: not from heap

    std::cout << "Avoided deleting stack variable\n\n";
}  // stack_widget destroyed here automatically

int main() {
    std::cout << "=== Deallocation Undefined Behavior Demo ===\n\n";

    demonstrate_safe_null_delete();
    demonstrate_mismatched_delete();
    demonstrate_double_delete();
    demonstrate_use_after_free();
    demonstrate_stack_delete();

    std::cout << "=== Summary ===\n";
    std::cout << "SAFE: delete nullptr\n";
    std::cout << "UB: delete ptr; delete ptr; (double-delete)\n";
    std::cout << "UB: new T[] + delete (should be delete[])\n";
    std::cout << "UB: new T + delete[] (should be delete)\n";
    std::cout << "UB: *ptr after delete (use-after-free)\n";
    std::cout << "UB: delete &stack_var (non-heap memory)\n";

    return 0;
}

// Output:
// === Deallocation Undefined Behavior Demo ===
//
// === Safe: Deleting null pointer ===
// No crash - null delete is safe
//
// === UNDEFINED: Mismatched new[]/delete ===
// Widget 1 constructed
// Widget 2 constructed
// Widget 3 constructed
// Widget 3 destroyed
// Widget 2 destroyed
// Widget 1 destroyed
// Used correct delete[] for array
//
// === UNDEFINED: Double delete ===
// Widget 100 constructed
// Widget 100 destroyed
// Avoided double-delete by commenting it out
//
// === UNDEFINED: Use-after-free ===
// Widget 200 constructed
// Widget 200 destroyed
// Nulled pointer after delete - safe check
//
// === UNDEFINED: Deleting stack variable ===
// Widget 300 constructed
// Avoided deleting stack variable
// Widget 300 destroyed
//
// === Summary ===
// SAFE: delete nullptr
// UB: delete ptr; delete ptr; (double-delete)
// UB: new T[] + delete (should be delete[])
// UB: new T + delete[] (should be delete)
// UB: *ptr after delete (use-after-free)
// UB: delete &stack_var (non-heap memory)
